# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">İZMİR\'İN İŞGALİ (15 MAYIS 1919), AMİRAL BRİSTOL VE KUVÂ-YI MİLLÎYE</text>\n\n  <!-- Sol Kutu: İzmir\'in İşgali ve İlk Kurşun -->\n  <rect x="18" y="45" width="325" height="198" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be123c">İZMİR\'İN İŞGALİ (15 MAYIS 1919)</text>\n  <line x1="32" y1="76" x2="328" y2="76" stroke="#fda4af" stroke-width="1.5"/>\n  <text x="32" y="98" font-size="10.5" fill="#881337">• Paris Barış Konferansı\'nda İngiltere\'nin desteğiyle</text>\n  <text x="40" y="114" font-size="10.5" fill="#881337">İzmir ve çevresi Yunanistan\'a verildi.</text>\n  <text x="32" y="136" font-size="10.5" font-weight="bold" fill="#9f1239">• Hasan Tahsin (Osman Nevres):</text>\n  <text x="40" y="152" font-size="10" fill="#881337">Hukuk-ı Beşer gazetesi başyazarı; İzmir\'de işgalcilere</text>\n  <text x="40" y="166" font-size="10" fill="#881337">ilk kurşunu atarak şehit düştü.</text>\n  <text x="32" y="186" font-size="10.5" font-weight="bold" fill="#9f1239">• Albay Süleyman Fethi Bey:</text>\n  <text x="40" y="202" font-size="10" fill="#881337">"Zito Venizelos" demeyi reddederek şehit edildi.</text>\n  <rect x="30" y="210" width="300" height="24" rx="5" fill="#ffe4e6" stroke="#f43f5e"/>\n  <text x="180" y="226" text-anchor="middle" font-size="10" font-weight="bold" fill="#be123c">Amiral Bristol Raporu: Haklılığımızı belirten ilk uluslararası belge!</text>\n\n  <!-- Sağ Kutu: Kuvâ-yı Millîye Ruhu -->\n  <rect x="358" y="45" width="324" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">KUVÂ-YI MİLLÎYE (MİLLÎ KUVVETLER)</text>\n  <line x1="372" y1="76" x2="668" y2="76" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="372" y="98" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Doğuş Nedenleri:</text>\n  <text x="380" y="114" font-size="10" fill="#1e40af">Osmanlı ordularının terhis edilmesi ve İstanbul</text>\n  <text x="380" y="128" font-size="10" fill="#1e40af">Hükûmeti\'nin işgallere karşı sessiz kalması.</text>\n  <text x="372" y="150" font-size="10.5" font-weight="bold" fill="#1e3a8a">• İlk Direniş Noktaları:</text>\n  <text x="380" y="166" font-size="10" fill="#1e40af">- Güney Cephesi: Hatay Dörtyol (Fransızlara karşı)</text>\n  <text x="380" y="182" font-size="10" fill="#1e40af">- Batı Cephesi: Ayvalık ve Ödemiş (Yunanlara karşı)</text>\n  <rect x="372" y="196" width="296" height="36" rx="5" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="520" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">İşgalleri yavaşlattı, iç isyanları bastırdı, düzenli</text>\n  <text x="520" y="226" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">ordunun kurulması için zaman kazandırdı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MÜTAREKE DÖNEMİNDE CEMİYETLER</text>\n\n  <!-- Kart 1: Millî (Yararlı) Cemiyetler -->\n  <rect x="16" y="42" width="234" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="133" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">MİLLÎ (YARARLI) CEMİYETLER</text>\n  <line x1="28" y1="72" x2="238" y2="72" stroke="#86efac" stroke-width="1.5"/>\n  <text x="26" y="90" font-size="9.5" fill="#14532d">• Trakya-Paşaeli Müdafaa-i Hukuk C.</text>\n  <text x="26" y="108" font-size="9.5" fill="#14532d">• İzmir Müdafaa-i Hukuk ve Redd-i İlhak</text>\n  <text x="26" y="126" font-size="9.5" fill="#14532d">• Şarkî Anadolu Müdafaa-i Hukuk C.</text>\n  <text x="26" y="144" font-size="9.5" fill="#14532d">• Trabzon Muhafaza-i Hukuk-ı Millîye</text>\n  <text x="26" y="162" font-size="9.5" fill="#14532d">• Kilikyalılar Cemiyeti (Çukurova/Adana)</text>\n  <text x="26" y="180" font-size="9.5" font-weight="bold" fill="#166534">• Millî Kongre C. (Dr. Esat Işık / Basın)</text>\n  <text x="26" y="198" font-size="9.5" fill="#14532d">• Anadolu Kadınları Müdafaa-i Vatan C.</text>\n  <rect x="26" y="208" width="214" height="26" rx="4" fill="#dcfce7"/>\n  <text x="133" y="225" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">Sivas\'ta ARMHC çatısında birleşti!</text>\n\n  <!-- Kart 2: Azınlıkların Kurduğu Zararlı Cemiyetler -->\n  <rect x="262" y="42" width="208" height="202" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="366" y="64" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#be123c">AZINLIK CEMİYETLERİ</text>\n  <line x1="274" y1="72" x2="458" y2="72" stroke="#fda4af" stroke-width="1.5"/>\n  <text x="272" y="94" font-size="10" font-weight="bold" fill="#881337">• Mavri Mira ve Etnik-i Eterya:</text>\n  <text x="278" y="108" font-size="9.5" fill="#9f1239">Bizans\'ı canlandırma (Megali İdea)</text>\n  <text x="272" y="128" font-size="10" font-weight="bold" fill="#881337">• Pontus Rum Cemiyeti:</text>\n  <text x="278" y="142" font-size="9.5" fill="#9f1239">Doğu Karadeniz\'de Rum devleti</text>\n  <text x="272" y="162" font-size="10" font-weight="bold" fill="#881337">• Hınçak ve Taşnak C.:</text>\n  <text x="278" y="176" font-size="9.5" fill="#9f1239">Doğu ve Çukurova\'da Ermenistan</text>\n  <text x="272" y="196" font-size="10" font-weight="bold" fill="#881337">• Alyans İsrailit ve Makabi C.:</text>\n  <text x="278" y="210" font-size="9.5" fill="#9f1239">Filistin\'de İsrail devleti kurma</text>\n\n  <!-- Kart 3: Millî Varlığa Düşman Cemiyetler -->\n  <rect x="482" y="42" width="202" height="202" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="583" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">MİLLÎ VARLIĞA DÜŞMAN C.</text>\n  <line x1="494" y1="72" x2="672" y2="72" stroke="#fde047" stroke-width="1.5"/>\n  <text x="492" y="96" font-size="10" fill="#713f12">• Sulh ve Selamet-i Osmaniye</text>\n  <text x="492" y="118" font-size="10" fill="#713f12">• Teali-i İslam Cemiyeti</text>\n  <text x="492" y="140" font-size="10" fill="#713f12">• Kürt Teali Cemiyeti</text>\n  <text x="492" y="162" font-size="10" font-weight="bold" fill="#854d0e">• İngiliz Muhipleri Cemiyeti</text>\n  <text x="498" y="176" font-size="9" fill="#713f12">(İngiliz mandasını savundu)</text>\n  <text x="492" y="198" font-size="10" font-weight="bold" fill="#854d0e">• Wilson Prensipleri Cemiyeti</text>\n  <text x="498" y="212" font-size="9" fill="#713f12">(ABD mandasını savundu)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">MİLLÎ MÜCADELE\'YE HAZIRLIK: SAMSUN\'DAN ANKARA\'YA (1919)</text>\n\n  <!-- Üst Sıra: Samsun -> Havza -> Amasya -->\n  <rect x="16" y="42" width="212" height="92" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="122" y="60" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">1. SAMSUN (19 Mayıs 1919)</text>\n  <text x="122" y="78" text-anchor="middle" font-size="9.5" fill="#1e3a8a">• 9. Ordu Müfettişi olarak çıktı</text>\n  <text x="122" y="94" text-anchor="middle" font-size="9.5" fill="#1e3a8a">• Samsun Raporu yayımlandı</text>\n  <text x="122" y="112" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">2. HAVZA (28 Mayıs 1919)</text>\n  <text x="122" y="126" text-anchor="middle" font-size="9.5" fill="#1e3a8a">• İşgallere karşı mitingler istendi</text>\n\n  <rect x="244" y="42" width="212" height="92" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="2"/>\n  <text x="350" y="60" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">3. AMASYA GENELGESİ (22 Haz)</text>\n  <text x="350" y="78" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#713f12">Gerekçe, Amaç ve Yöntem:</text>\n  <text x="350" y="94" text-anchor="middle" font-size="9" fill="#854d0e">"Milletin bağımsızlığını yine milletin</text>\n  <text x="350" y="108" text-anchor="middle" font-size="9" fill="#854d0e">azim ve kararı kurtaracaktır."</text>\n  <text x="350" y="124" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#a16207">• Sivas\'ta ulusal kongre çağrısı</text>\n\n  <rect x="472" y="42" width="212" height="92" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="578" y="60" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">4. ERZURUM (23 Tem - 7 Ağu)</text>\n  <text x="578" y="78" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#9a3412">Toplanışı Bölgesel, Kararları Ulusal</text>\n  <text x="578" y="94" text-anchor="middle" font-size="9" fill="#7c2d12">• "Vatan bir bütündür, parçalanamaz"</text>\n  <text x="578" y="108" text-anchor="middle" font-size="9" fill="#7c2d12">• İlk kez manda ve himaye reddedildi</text>\n  <text x="578" y="124" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#c2410c">• 9 kişilik Temsil Heyeti seçildi</text>\n\n  <!-- Alt Sıra: Sivas -> Amasya Görüşmeleri -> Ankara -->\n  <rect x="16" y="148" width="330" height="96" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="181" y="168" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">5. SİVAS KONGRESİ (4 - 11 Eylül 1919) - HER YÖNÜYLE ULUSAL</text>\n  <text x="28" y="186" font-size="9.5" fill="#14532d">• Tüm cemiyetler ARMHC adıyla birleştirildi; manda kesin reddedildi.</text>\n  <text x="28" y="204" font-size="9.5" fill="#14532d">• İrade-i Millîye gazetesi çıkarıldı; Temsil Heyeti tüm vatanı temsil etti.</text>\n  <text x="28" y="222" font-size="9.5" font-weight="bold" fill="#166534">• Ali Fuat Paşa Batı Cephesi\'ne atandı (Yürütme yetkisi kullanıldı).</text>\n\n  <rect x="362" y="148" width="322" height="96" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="523" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">6. AMASYA GÖRÜŞMELERİ VE ANKARA</text>\n  <text x="374" y="188" font-size="9.5" fill="#581c87">• Damat Ferit istifa etti; Ali Rıza Paşa Hükûmeti kuruldu.</text>\n  <text x="374" y="206" font-size="9.5" font-weight="bold" fill="#6b21a8">• Amasya Görüşmeleri (20-22 Ekim): Temsil Heyeti resmen tanındı!</text>\n  <text x="374" y="224" font-size="9.5" font-weight="bold" fill="#3b0764">• 27 Aralık 1919: Temsil Heyeti Ankara\'ya geldi (Merkez).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
